    String normalizedFirst = normalizeString(firstName);
    String normalizedLast = normalizeString(lastName);

    return authorRepository
        .findByFirstNameAndLastName(normalizedFirst, normalizedLast)
        .orElseGet(() -> {
            Author author = Author.createAuthor(normalizedFirst, normalizedLast, null);
            return authorRepository.save(author);
        });
