public Book updateBook(Long id, BookUpdateRequest request) {
    Book book = getBookById(id);

    // 작가 변경 요청이 있으면
    Author author = null;
    if (request.getAuthorFirstName() != null && request.getAuthorLastName() != null) {
        author = findOrCreateAuthor(
            request.getAuthorFirstName(),
            request.getAuthorLastName()
        );
    }

    // Dirty Checking - @Transactional 내에서 엔티티 변경 시 자동 저장
    book.updateBookInfo(
        request.getTitle(),
        author,
        request.getPublisher(),
        request.getCategory(),
        request.getPublishedDate()
    );

    return book;
}

